"use client";

import { type KeyboardEvent, type PointerEvent as ReactPointerEvent, useEffect, useRef, useState } from "react";
import { useVersionComparison } from "./version-comparison-state";

const clampRatio = (value: number) => Math.round(Math.min(1, Math.max(0, value)) * 1000) / 1000;

/** The Swipe mode divider. Drag it or use the arrow keys. Escape cancels a drag. */
export function VersionComparisonDivider({ stageRef }: { stageRef: { current: HTMLDivElement | null } }) {
  const { divider, disabled, messages, setDivider, onDividerChange, onDividerCommit } = useVersionComparison();
  const stop = useRef<(() => void) | null>(null);
  const [dragging, setDragging] = useState(false);
  useEffect(() => () => stop.current?.(), []);

  const show = (next: number) => {
    setDivider(next);
    onDividerChange?.(next);
  };
  const onPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (disabled || event.button !== 0 || stop.current) return;
    event.currentTarget.dataset.pointerFocus = "";
    const pointerId = event.pointerId;
    const start = divider;
    let last = divider;
    const at = (clientX: number) => {
      const rect = stageRef.current?.getBoundingClientRect();
      return rect?.width ? clampRatio((clientX - rect.left) / rect.width) : last;
    };
    const listening = new AbortController();
    const { signal } = listening;
    const end = () => {
      listening.abort();
      stop.current = null;
      setDragging(false);
    };
    const cancel = () => {
      show(start);
      end();
    };
    window.addEventListener("pointermove", (next) => {
      if (next.pointerId !== pointerId) return;
      last = at(next.clientX);
      show(last);
    }, { signal });
    window.addEventListener("pointerup", (next) => {
      if (next.pointerId !== pointerId) return;
      if (last !== start) onDividerCommit?.(last);
      end();
    }, { signal });
    window.addEventListener("pointercancel", (next) => {
      if (next.pointerId === pointerId) cancel();
    }, { signal });
    window.addEventListener("blur", cancel, { signal });
    window.addEventListener("keydown", (next) => {
      if (next.key !== "Escape") return;
      next.preventDefault();
      next.stopPropagation();
      cancel();
    }, { signal, capture: true });
    stop.current = () => listening.abort();
    setDragging(true);
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const amount = event.shiftKey ? 0.1 : 0.01;
    const targets: Record<string, number> = { ArrowLeft: divider - amount, ArrowDown: divider - amount, ArrowRight: divider + amount, ArrowUp: divider + amount, Home: 0, End: 1 };
    const target = targets[event.key];
    if (disabled || target === undefined) return;
    event.preventDefault();
    const next = clampRatio(target);
    if (next === divider) return;
    show(next);
    onDividerCommit?.(next);
  };

  return (
    <>
      <span aria-hidden data-slot="version-comparison-divider-line" className="pointer-events-none absolute inset-y-0 z-[2] w-0.5 -translate-x-1/2 bg-primary" style={{ left: `${divider * 100}%` }} />
      <div
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={messages.divider}
        aria-orientation="horizontal"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(divider * 100)}
        aria-valuetext={`${Math.round(divider * 100)}%`}
        aria-disabled={disabled || undefined}
        data-slot="version-comparison-divider"
        data-dragging={dragging ? "" : undefined}
        className="group/divider absolute inset-y-0 z-[2] grid w-11 -translate-x-1/2 cursor-ew-resize touch-none place-items-center outline-none aria-disabled:cursor-default"
        // At either edge the handle bleeds off the stage with the line, so only half shows.
        style={{ left: `${divider * 100}%` }}
        onPointerDown={onPointerDown}
        onKeyDown={onKeyDown}
        onBlur={(event) => {
          delete event.currentTarget.dataset.pointerFocus;
        }}
      >
        <span aria-hidden className="relative grid size-7 place-items-center rounded-full bg-primary text-primary-foreground transition-transform group-data-dragging/divider:scale-110 group-focus-visible/divider:not-group-data-pointer-focus/divider:ring-2 group-focus-visible/divider:not-group-data-pointer-focus/divider:ring-ring motion-reduce:transition-none">
          <svg viewBox="0 0 16 16" className="size-4" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M6 4.5 2.5 8 6 11.5M10 4.5 13.5 8 10 11.5" />
          </svg>
        </span>
      </div>
    </>
  );
}

"use client";

import { ContextMenu, ContextMenuButton, ContextMenuContent, ContextMenuItem, ContextMenuTarget } from "@/components/ui/context-menu";
import { InlineEdit, InlineEditEditor, InlineEditError, InlineEditInput, InlineEditPreview } from "@/components/ui/inline-edit";
import { type ComparisonSlot, type ComparisonVersion, useVersionComparison } from "./version-comparison-state";
import { cn } from "@/lib/utils";

/** A version's letter and name on the stage, with Rename, Duplicate and Delete in its menu. */
export function VersionComparisonLabel({ version, slot, align = "left" }: { version: ComparisonVersion; slot: ComparisonSlot; align?: "left" | "right" }) {
  const { container, disabled, renamingId, messages, onRename, onDuplicate, onDelete, setRenamingId } = useVersionComparison();
  const hasActions = !!(onRename || onDuplicate || onDelete);
  return (
    <ContextMenu disabled={disabled || !hasActions}>
      <ContextMenuTarget
        data-slot="version-comparison-label"
        className={cn("group/label absolute top-2 z-[1] flex max-w-[calc(100%-5rem)] min-w-0 items-center gap-1 rounded-[5px] bg-background/90 py-0.5 pr-0.5 pl-1.5 text-xs text-foreground", align === "left" ? "left-2" : "right-2")}
      >
        <span className="font-medium">{slot === "a" ? messages.versionA : messages.versionB}</span>
        {onRename ? (
          <InlineEdit label={messages.name} value={version.name} variant="ghost" editing={renamingId === version.id} disabled={disabled} className="min-w-0" validate={(name) => (name.trim() ? null : messages.name)} onEditingChange={(editing) => setRenamingId(editing ? version.id : null)} onSave={(name) => onRename(version.id, name.trim())}>
            <InlineEditPreview className="block min-h-5 max-w-full truncate px-0.5 text-xs text-foreground/70 after:hidden" />
            <InlineEditEditor className="after:hidden">
              <InlineEditInput className="h-5 w-28 px-0.5 text-xs" />
            </InlineEditEditor>
            <InlineEditError className="text-xs" />
          </InlineEdit>
        ) : (
          <span className="min-w-0 truncate text-foreground/70">{version.name}</span>
        )}
        {hasActions && <ContextMenuButton aria-label={messages.actions(version.name)} className="relative size-5 shrink-0 after:absolute after:-inset-3 [&_svg]:size-3.5" />}
      </ContextMenuTarget>
      <ContextMenuContent container={container} positionMethod={container ? "fixed" : undefined}>
        {onRename && <ContextMenuItem onClick={() => setRenamingId(version.id)}>{messages.rename}</ContextMenuItem>}
        {onDuplicate && <ContextMenuItem onClick={() => onDuplicate(version.id)}>{messages.duplicate}</ContextMenuItem>}
        {onDelete && (
          <ContextMenuItem variant="destructive" disabled={version.current} onClick={() => onDelete(version.id)}>
            {messages.delete}
          </ContextMenuItem>
        )}
      </ContextMenuContent>
    </ContextMenu>
  );
}

"use client";

import { forwardRef, useState, useSyncExternalStore } from "react";
import { VersionComparisonChanges, VersionComparisonOpacity, VersionComparisonStage } from "./version-comparison-stage";
import { VersionComparisonToolbar } from "./version-comparison-toolbar";
import { type ComparisonMode, type ComparisonSlot, type VersionComparisonProps, VersionComparisonContext, defaultMessages } from "./version-comparison-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribePhone = (listener: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const query = window.matchMedia(phoneQuery);
  query.addEventListener("change", listener);
  return () => query.removeEventListener("change", listener);
};
const readPhone = () => (typeof window.matchMedia === "function" ? window.matchMedia(phoneQuery).matches : false);

/** Puts two design versions next to each other. Your app owns the versions and applies the choice. */
export const VersionComparison = forwardRef<HTMLDivElement, VersionComparisonProps>(function VersionComparison(
  {
    label,
    versions,
    compare,
    onCompareChange,
    renderVersion,
    changes,
    onUse,
    onRename,
    onDuplicate,
    onDelete,
    onRetry,
    defaultMode,
    onDividerChange,
    onDividerCommit,
    onOpacityChange,
    onOpacityCommit,
    aspectRatio = "16 / 10",
    container,
    disabled = false,
    messages: messageOverrides,
    className,
    children,
    ...props
  },
  ref,
) {
  const messages = { ...defaultMessages, ...messageOverrides };
  const phone = useSyncExternalStore(subscribePhone, readPhone, () => false);
  const [chosenMode, setMode] = useState<ComparisonMode | null>(defaultMode ?? null);
  const [divider, setDivider] = useState(0.5);
  const [opacity, setOpacity] = useState(0.5);
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const find = (id: string | null) => versions.find((version) => version.id === id) ?? null;
  const { a, b } = compare;

  const chooseSlot = (slot: ComparisonSlot, id: string) => {
    if (id === (slot === "a" ? a : b)) return;
    if (id === (slot === "a" ? b : a)) onCompareChange({ a: b, b: a });
    else onCompareChange(slot === "a" ? { a: id, b } : { a, b: id });
  };

  return (
    <VersionComparisonContext.Provider
      value={{
        versions,
        compare,
        renderVersion,
        changes,
        onUse,
        onRename,
        onDuplicate,
        onDelete,
        onRetry,
        onDividerChange,
        onDividerCommit,
        onOpacityChange,
        onOpacityCommit,
        container,
        versionA: find(a),
        versionB: find(b),
        mode: chosenMode ?? (phone ? "swipe" : "side"),
        divider,
        opacity,
        aspectRatio,
        disabled,
        renamingId,
        messages,
        setMode,
        setDivider,
        setOpacity,
        setRenamingId,
        chooseSlot,
        swap: () => onCompareChange({ a: b, b: a }),
      }}
    >
      <div ref={ref} role="group" aria-label={label} data-slot="version-comparison" data-disabled={disabled ? "" : undefined} className={cn("@container/versions grid w-full min-w-0 content-start gap-3 text-sm", className)} {...props}>
        {children ?? (
          <>
            <VersionComparisonToolbar />
            <VersionComparisonStage />
            <VersionComparisonOpacity />
            <VersionComparisonChanges />
          </>
        )}
      </div>
    </VersionComparisonContext.Provider>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type CSSProperties, type ReactNode, forwardRef, useRef } from "react";
import { NumberField, NumberFieldLabel, NumberFieldSlider, NumberFieldSliderFill, NumberFieldSliderThumb, NumberFieldValue } from "@/components/ui/number-field";
import { VersionComparisonDivider } from "./version-comparison-divider";
import { VersionComparisonLabel } from "./version-comparison-label";
import { type ComparisonSlot, type ComparisonVersion, useVersionComparison } from "./version-comparison-state";
import { cn } from "@/lib/utils";

function UseButton({ version, align = "right", top = false }: { version: ComparisonVersion | null; align?: "left" | "right"; top?: boolean }) {
  const { disabled, messages, onUse } = useVersionComparison();
  if (!onUse || !version || version.current || (version.status ?? "ready") !== "ready") return null;
  return (
    <button
      type="button"
      aria-label={messages.use(version.name)}
      disabled={disabled}
      className={cn("absolute z-[3] h-7 rounded-[5px] bg-primary px-2.5 text-xs font-medium text-primary-foreground outline-none transition-colors hover:bg-primary/90 focus-visible:ring-2 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none pointer-coarse:h-11 pointer-coarse:px-4", top ? "top-1.5 h-6 px-2" : "bottom-2", align === "left" ? "left-2" : "right-2")}
      onClick={() => onUse(version.id)}
    >
      {messages.useShort}
    </button>
  );
}

function Pane({ version, slot, align = "left", className, style, children }: { version: ComparisonVersion | null; slot: ComparisonSlot; align?: "left" | "right"; className?: string; style?: CSSProperties; children?: ReactNode }) {
  const { renderVersion, onRetry, disabled, messages } = useVersionComparison();
  const status = version?.status ?? "ready";
  const letter = slot === "a" ? messages.versionA : messages.versionB;
  return (
    <div role="group" aria-label={version ? `${letter}: ${version.name}` : letter} aria-busy={status === "loading" || undefined} data-slot="version-comparison-pane" data-version-slot={slot} className={cn("overflow-hidden rounded-md bg-foreground/5", className)} style={style}>
      <div className="absolute inset-0 grid place-items-center">
        {version && status === "ready" && renderVersion(version, { slot, size: "stage" })}
        {status === "loading" && <span role="status" aria-label={messages.loading} className="size-6 animate-spin rounded-full border-2 border-foreground/20 border-t-foreground motion-reduce:animate-none" />}
        {status === "error" && (
          <span className="grid justify-items-center gap-2 px-4 text-center text-muted-foreground">
            {messages.failed}
            {onRetry && version && (
              <button type="button" disabled={disabled} className="h-9 rounded-md bg-foreground/8 px-3 text-foreground outline-none hover:bg-foreground/15 focus-visible:bg-foreground/15 disabled:opacity-40 pointer-coarse:h-11" onClick={() => onRetry(version.id)}>
                {messages.retry}
              </button>
            )}
          </span>
        )}
      </div>
      {version && <VersionComparisonLabel version={version} slot={slot} align={align} />}
      {children}
    </div>
  );
}

/** The two versions, drawn for the current mode. */
export const VersionComparisonStage = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function VersionComparisonStage({ className, style, ...props }, ref) {
  const { versions, versionA, versionB, mode, divider, opacity, aspectRatio, messages } = useVersionComparison();
  const stageRef = useRef<HTMLDivElement | null>(null);
  const ratio = { aspectRatio };
  if (versions.length < 2) {
    return (
      <div ref={ref} data-slot="version-comparison-empty" className={cn("grid place-items-center rounded-md bg-foreground/5 px-4 text-center text-muted-foreground", className)} style={{ ...ratio, ...style }} {...props}>
        {messages.needTwo}
      </div>
    );
  }
  if (mode === "side") {
    return (
      <div ref={ref} data-slot="version-comparison-stage" data-mode={mode} className={cn("grid min-w-0 grid-cols-2 gap-2 @max-md/versions:grid-cols-1", className)} style={style} {...props}>
        <Pane version={versionA} slot="a" className="relative" style={ratio}>
          <UseButton version={versionA} top />
        </Pane>
        <Pane version={versionB} slot="b" className="relative" style={ratio}>
          <UseButton version={versionB} top />
        </Pane>
      </div>
    );
  }
  const top: CSSProperties = mode === "swipe" ? { clipPath: `inset(0 0 0 ${divider * 100}%)` } : { opacity };
  return (
    <div
      ref={(node) => {
        stageRef.current = node;
        if (typeof ref === "function") ref(node);
        else if (ref) ref.current = node;
      }}
      data-slot="version-comparison-stage"
      data-mode={mode}
      className={cn("relative min-w-0 overflow-hidden rounded-md select-none", className)}
      style={{ ...ratio, ...style }}
      {...props}
    >
      <Pane version={versionA} slot="a" className="absolute inset-0" />
      <Pane version={versionB} slot="b" align="right" className="absolute inset-0" style={top} />
      {mode === "swipe" && <VersionComparisonDivider stageRef={stageRef} />}
      {/* Outside the panes, so moving the divider never clips them. */}
      <UseButton version={versionA} align="left" />
      <UseButton version={versionB} />
    </div>
  );
});

/** How strongly B shows over A. It appears in Overlay mode. */
export const VersionComparisonOpacity = forwardRef<HTMLDivElement, Omit<ComponentPropsWithoutRef<"div">, "children" | "defaultValue">>(function VersionComparisonOpacity({ className, ...props }, ref) {
  const { versions, mode, opacity, disabled, messages, setOpacity, onOpacityChange, onOpacityCommit } = useVersionComparison();
  if (versions.length < 2 || mode !== "overlay") return null;
  return (
    <NumberField
      ref={ref}
      data-slot="version-comparison-opacity"
      label={messages.opacity}
      value={Math.round(opacity * 100)}
      min={0}
      max={100}
      step={1}
      unit="%"
      disabled={disabled}
      className={cn("min-w-0", className)}
      onValueChange={(next) => {
        setOpacity(next / 100);
        onOpacityChange?.(next / 100);
      }}
      onValueCommit={(next) => {
        setOpacity(next / 100);
        onOpacityCommit?.(next / 100);
      }}
      {...props}
    >
      <NumberFieldSlider className="h-9 pointer-coarse:h-11">
        <NumberFieldSliderFill />
        <NumberFieldSliderThumb />
        <NumberFieldLabel />
        <NumberFieldValue />
      </NumberFieldSlider>
    </NumberField>
  );
});

/** What differs between A and B, one row per property. It shows when your app passes changes. */
export const VersionComparisonChanges = forwardRef<HTMLDListElement, ComponentPropsWithoutRef<"dl">>(function VersionComparisonChanges({ className, ...props }, ref) {
  const { changes, messages } = useVersionComparison();
  if (!changes?.length) return null;
  return (
    <dl ref={ref} aria-label={messages.changes} data-slot="version-comparison-changes" className={cn("grid min-w-0 gap-1", className)} {...props}>
      {changes.map((change) => (
        <div key={change.label} className="flex h-9 min-w-0 items-center justify-between gap-3 rounded-md bg-foreground/8 px-2.5 pointer-coarse:h-11">
          <dt className="min-w-0 truncate text-foreground/80">{change.label}</dt>
          <dd className="flex min-w-0 shrink-0 items-center gap-1.5 font-mono text-xs text-foreground tabular-nums">
            <span className="truncate text-foreground/60">{change.before}</span>
            <span aria-hidden className="text-foreground/50">→</span>
            <span className="sr-only">to</span>
            <span className="truncate">{change.after}</span>
          </dd>
        </div>
      ))}
    </dl>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, createContext, useContext, useEffect, useLayoutEffect } from "react";

export const useIsomorphicLayoutEffect = typeof window === "undefined" ? useEffect : useLayoutEffect;

export type ComparisonVersion = {
  id: string;
  name: string;
  /** The version in use now. It gets the Current label and is what the strip compares against. */
  current?: boolean;
  status?: "ready" | "loading" | "error";
};
export type ComparisonChange = { label: string; before: string; after: string };
export type ComparisonMode = "side" | "swipe" | "overlay";
export type ComparisonSlot = "a" | "b";
export type ComparisonPair = { a: string | null; b: string | null };
export type ComparisonRenderDetail = { slot: ComparisonSlot | null; size: "stage" | "thumbnail" };

/** Replaceable text, for example to translate. */
export type VersionComparisonMessages = {
  versionA: string;
  versionB: string;
  swap: string;
  mode: string;
  side: string;
  swipe: string;
  overlay: string;
  divider: string;
  opacity: string;
  current: string;
  changes: string;
  versions: string;
  actions: (name: string) => string;
  compare: (name: string) => string;
  use: (name: string) => string;
  useShort: string;
  name: string;
  rename: string;
  duplicate: string;
  delete: string;
  loading: string;
  failed: string;
  retry: string;
  needTwo: string;
};

export const defaultMessages: VersionComparisonMessages = {
  versionA: "A",
  versionB: "B",
  swap: "Swap versions",
  mode: "Comparison mode",
  side: "Side by side",
  swipe: "Swipe",
  overlay: "Overlay",
  divider: "Comparison divider",
  opacity: "B opacity",
  current: "Current",
  changes: "Changes",
  versions: "Versions",
  actions: (name) => `${name} actions`,
  compare: (name) => `Compare ${name}`,
  use: (name) => `Use ${name}`,
  useShort: "Use",
  name: "Version name",
  rename: "Rename",
  duplicate: "Duplicate",
  delete: "Delete",
  loading: "Loading version",
  failed: "This version could not load.",
  retry: "Retry",
  needTwo: "Add another version to compare.",
};

export type VersionComparisonProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "defaultValue"> & {
  /** Names the panel for screen readers. */
  label: string;
  /** The alternatives. Your app owns them. */
  versions: ComparisonVersion[];
  /** The versions being compared. Your app owns them. */
  compare: ComparisonPair;
  onCompareChange: (pair: ComparisonPair) => void;
  /** Draws a version for the stage or the strip. It can return an image, a screen or live UI. */
  renderVersion: (version: ComparisonVersion, detail: ComparisonRenderDetail) => ReactNode;
  /** What differs between A and B, if your app knows. Passing it shows the list. */
  changes?: ComparisonChange[];
  /** Passing it shows a Use button on each version that can be chosen. Your app applies the version. */
  onUse?: (id: string) => void;
  /** Passing it lets people rename versions. Return a promise to show saving. */
  onRename?: (id: string, name: string) => void | Promise<unknown>;
  /** Passing it adds Duplicate to the menu. */
  onDuplicate?: (id: string) => void;
  /** Passing it adds Delete to the menu. The current version cannot be deleted. */
  onDelete?: (id: string) => void;
  /** Passing it offers Retry on a version that failed to load. */
  onRetry?: (id: string) => void;
  /** The starting mode. Phones start on Swipe, other screens on Side by side. */
  defaultMode?: ComparisonMode;
  /** Called with live divider positions from 0 to 1, and the start when a drag is cancelled. */
  onDividerChange?: (position: number) => void;
  onDividerCommit?: (position: number) => void;
  /** Called with live overlay opacity from 0 to 1, and the committed value when a drag is cancelled. */
  onOpacityChange?: (opacity: number) => void;
  onOpacityCommit?: (opacity: number) => void;
  /** The stage's shape as a CSS aspect ratio. */
  aspectRatio?: string;
  /** Where menus are portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  disabled?: boolean;
  messages?: Partial<VersionComparisonMessages>;
};

export type VersionComparisonContextValue = Pick<VersionComparisonProps, "versions" | "compare" | "renderVersion" | "changes" | "onUse" | "onRename" | "onDuplicate" | "onDelete" | "onRetry" | "onDividerChange" | "onDividerCommit" | "onOpacityChange" | "onOpacityCommit" | "container"> & {
  versionA: ComparisonVersion | null;
  versionB: ComparisonVersion | null;
  mode: ComparisonMode;
  divider: number;
  opacity: number;
  aspectRatio: string;
  disabled: boolean;
  renamingId: string | null;
  messages: VersionComparisonMessages;
  setMode: (mode: ComparisonMode) => void;
  setDivider: (position: number) => void;
  setOpacity: (opacity: number) => void;
  setRenamingId: (id: string | null) => void;
  chooseSlot: (slot: ComparisonSlot, id: string) => void;
  swap: () => void;
};

export const VersionComparisonContext = createContext<VersionComparisonContextValue | null>(null);

/** The compared versions and view state of the nearest VersionComparison, for custom parts. */
export function useVersionComparison() {
  const context = useContext(VersionComparisonContext);
  if (!context) throw new Error("Version Comparison parts must be rendered inside <VersionComparison>.");
  return context;
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldSegments, InspectorFieldSelect } from "@/components/ui/inspector-field";
import { type ComparisonMode, type ComparisonSlot, useVersionComparison } from "./version-comparison-state";
import { cn } from "@/lib/utils";

export const filledField = "[--uicoolkit-field-bg:color-mix(in_oklab,var(--foreground)_8%,transparent)] [--uicoolkit-field-border:transparent] [--uicoolkit-field-height:2.25rem] [--uicoolkit-field-shadow:none] pointer-coarse:[--uicoolkit-field-height:2.75rem]";

const icon = (path: string) => (
  <svg aria-hidden viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    <path d={path} />
  </svg>
);
const modeIcons: Record<ComparisonMode, React.ReactNode> = {
  side: icon("M2.5 3.5h4.5v9H2.5ZM9 3.5h4.5v9H9Z"),
  swipe: icon("M2.5 3.5h11v9h-11ZM8 1.75v12.5"),
  overlay: icon("M2.5 2.5h8v8h-8ZM5.5 5.5h8v8h-8Z"),
};

function VersionSelect({ slot }: { slot: ComparisonSlot }) {
  const { versions, compare, renderVersion, container, disabled, messages, chooseSlot } = useVersionComparison();
  const renderOption = (option: { value: string }) => {
    const version = versions.find((item) => item.id === option.value);
    if (!version) return null;
    // The field shows only the name; the open menu adds a thumbnail and the Current label.
    return (
      <span className="inline-flex max-w-full min-w-0 items-center gap-2.5">
        <span aria-hidden className="relative h-9 w-12 shrink-0 overflow-hidden rounded-[4px] bg-foreground/8 in-[button]:hidden">
          {(version.status ?? "ready") === "ready" && renderVersion(version, { slot: null, size: "thumbnail" })}
        </span>
        <span className="min-w-0 truncate">{version.name}</span>
        {version.current && <span className="shrink-0 text-xs text-foreground/60 in-[button]:hidden">{messages.current}</span>}
      </span>
    );
  };
  return (
    <InspectorField label={slot === "a" ? messages.versionA : messages.versionB} labelPosition="inside" disabled={disabled} className={cn("min-w-0 flex-1", filledField)}>
      <InspectorFieldLabel />
      <InspectorFieldSelect value={compare[slot] ?? ""} options={versions.map((version) => ({ value: version.id, label: version.name }))} container={container} positionMethod={container ? "fixed" : undefined} itemClassName="py-1" renderOption={renderOption} onCommit={(id) => chooseSlot(slot, id)} />
    </InspectorField>
  );
}

/** The A and B selects, Swap and the comparison mode. */
export const VersionComparisonToolbar = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function VersionComparisonToolbar({ className, ...props }, ref) {
  const { versions, compare, mode, disabled, messages, setMode, swap } = useVersionComparison();
  return (
    // Two halves with the stage's gap, so Swap ends where the A pane ends in Side by side. Once the panes stack, A and B share the width equally.
    <div ref={ref} data-slot="version-comparison-toolbar" className={cn("grid min-w-0 grid-cols-2 items-center gap-2 @max-md/versions:grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)]", className)} {...props}>
      <div className="flex min-w-0 items-center gap-2 @max-md/versions:contents">
        <VersionSelect slot="a" />
        <button
          type="button"
          aria-label={messages.swap}
          title={messages.swap}
          disabled={disabled || versions.length < 2 || !compare.a || !compare.b}
          className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-foreground/8 text-foreground outline-none transition-colors hover:bg-foreground/15 focus-visible:bg-foreground/15 disabled:pointer-events-none disabled:opacity-40 motion-reduce:transition-none pointer-coarse:size-11 [&_svg]:size-4"
          onClick={swap}
        >
          {icon("M2.5 5.5h10M10 3l2.5 2.5L10 8M13.5 10.5h-10M6 8l-2.5 2.5L6 13")}
        </button>
      </div>
      <div className="flex min-w-0 items-center gap-2 @max-lg/versions:contents">
        <VersionSelect slot="b" />
        <InspectorField label={messages.mode} disabled={disabled} className={cn("block w-30 min-w-0 shrink-0 @max-lg/versions:col-span-full @max-lg/versions:w-auto", filledField)}>
          <InspectorFieldLabel className="sr-only" />
          <InspectorFieldSegments
            className="h-(--uicoolkit-field-height) w-full"
            value={mode}
            options={(["side", "swipe", "overlay"] as const).map((value) => ({ value, label: messages[value], icon: modeIcons[value] }))}
            onCommit={setMode}
          />
        </InspectorField>
      </div>
    </div>
  );
});

